"Алтыбакан — большие качели, их ставят на праздниках.": "L'altybakan est une grande balançoire que l'on installe lors des fêtes.",
"Асык — игра с косточками-альчиками.": "L'assyk est un jeu avec des osselets.",
"Аударыспак — борьба двух всадников верхом.": "L'aoudarys­pak est une lutte entre deux cavaliers à cheval.",
"Байга — скачки на лошадях.": "La baïga est une course de chevaux.",
"Бегун наклоняется вперёд и быстро двигает ногами и руками.": "Le coureur se penche en avant et bouge vite les jambes et les bras.",
"Быстрее, дальше, точнее! Давай узнаем, как бегают, прыгают и бросают. Нажимай на карточки.": "Plus vite, plus loin, plus précis ! Découvrons comment on court, saute et lance. Appuie sur les cartes.",
