"В команде вместе легче победить. Нужно помогать друг другу.": "En équipe, il est plus facile de gagner. Il faut s'entraider.",
"В командной игре важно не только победить. Давай узнаем, как играть дружно и честно. Нажимай на карточки.": "Dans un jeu d'équipe, il ne suffit pas de gagner. Découvrons comment jouer en bonne entente et loyalement. Appuie sur les cartes.",
"В эстафете команды бегут по очереди и передают палочку или флажок.": "Dans une course de relais, les équipes courent à tour de rôle et se passent un bâton ou un fanion.",
"Верно или неверно? Подумай и выбери ответ.": "Vrai ou faux ? Réfléchis et choisis la réponse.",
"Вышибалы, футбол и мяч капитану — игры с мячом.": "La balle au prisonnier, le football et la balle au capitaine sont des jeux de balle.",
"Гимнастика делает нас ловкими и сильными. Нажимай на карточки и узнавай, как держать равновесие и спину.": "La gymnastique nous rend agiles et forts. Appuie sur les cartes et découvre comment garder l'équilibre et le dos droit.",
"Двигаться полезно и дома, и в школе: зарядка, прогулки, игры и урок физкультуры.": "Bouger est utile à la maison comme à l'école : gymnastique, promenades, jeux et cours d'éducation physique.",
"Если что-то болит, нужно сразу сказать учителю.": "Si quelque chose fait mal, il faut le dire tout de suite à l'enseignant.",
