"Капитан ведёт команду и подбадривает игроков.": "Le capitaine mène l'équipe et encourage les joueurs.",
"Когда мышцы работают, телу становится жарко. После нагрузки нужно отдохнуть.": "Quand les muscles travaillent, le corps a chaud. Après l'effort, il faut se reposer.",
"Когда сутулишься, спина согнута, а голова наклонена вперёд. Так вредно для здоровья.": "Quand on se voûte, le dos est courbé et la tête penchée en avant. C'est mauvais pour la santé.",
"Кокпар — командная игра верхом на лошадях.": "Le kokpar est un jeu d'équipe à cheval.",
"Круги руками разминают плечи.": "Les rotations des bras échauffent les épaules.",
"Лазать по гимнастической стенке нужно осторожно и вместе с учителем.": "Il faut grimper au mur de gymnastique avec précaution et avec l'enseignant.",
"Мяч бросают двумя руками от груди в цель или партнёру.": "On lance le ballon à deux mains depuis la poitrine vers une cible ou vers un partenaire.",
"Мяч бросают, ловят, передают и ведут.": "On lance, on attrape, on passe et on dribble le ballon.",
"Мяч ловят двумя руками и смотрят на него.": "On attrape le ballon à deux mains en le regardant.",
"💡 Форму вещей придумывает дизайнер": "💡 La forme des objets est imaginée par un designer",
