"Поздравляю! Ты узнал про семью, школу, родной край, карту, город, права, погоду, путешествия, историю и символы Казахстана. Теперь закрепляй знания в играх.": "Bravo ! Tu as découvert la famille, l'école, la région natale, la carte, la ville, les droits, la météo, les voyages, l'histoire et les symboles du Kazakhstan. Maintenant, consolide tes connaissances dans les jeux.",
