"Тёплое долгое лето": "Un été chaud et long",
"Тёплое солнце летом": "Un soleil chaud en été",
"Тёплую одежду, воду и удобную обувь": "Des vêtements chauds, de l'eau et des chaussures confortables",
"Тёплый дождь весной": "Une pluie chaude au printemps",
"Тёплый дождь весной помогает расти растениям": "Une pluie chaude au printemps aide les plantes à pousser",
"У каждого края своя природа. Горы, равнины, реки и озёра помогают людям по-разному. Нажимай на карточки и узнавай.": "Chaque région a sa propre nature. Les montagnes, les plaines, les rivières et les lacs aident les gens de différentes façons. Appuie sur les cartes et découvre.",
"У каждого ребёнка есть право на образование": "Chaque enfant a droit à l'éducation",
"У каждого ребёнка есть право учиться в школе": "Chaque enfant a le droit d'aller à l'école",
"У каждого человека есть права и обязанности. Давай разберёмся, что это такое, и вспомним главные праздники страны. Нажимай на карточки.": "Chaque personne a des droits et des devoirs. Comprenons ce que c'est et rappelons-nous les principales fêtes du pays. Appuie sur les cartes.",
"У каждой местности есть свои плюсы и свои трудности": "Chaque région a ses avantages et ses difficultés",
"У каждой семьи могут быть свои обычаи и правила": "Chaque famille peut avoir ses propres coutumes et règles",
"У каждой страны есть главные символы. Давай познакомимся с символами Казахстана. Нажимай на карточки.": "Chaque pays a ses principaux symboles. Faisons connaissance avec les symboles du Kazakhstan. Appuie sur les cartes.",
"У разных народов могут быть свои праздники и обычаи": "Différents peuples peuvent avoir leurs propres fêtes et coutumes",
