"💡 Аль-Фараби был великим учёным, его назвали «Вторым учителем»": "💡 Al-Farabi était un grand savant, on l'appelait le « Deuxième Maître »",
"💡 Аль-Фараби родился в Фарабе — так раньше называли город Отрар": "💡 Al-Farabi est né à Farab — c'est ainsi qu'on appelait autrefois la ville d'Otrar",
"💡 Астана — столица Казахстана. Она находится в центре страны, на реке Есиль": "💡 Astana est la capitale du Kazakhstan. Elle se trouve au centre du pays, sur la rivière Ichim",
"💡 Ботайская культура — культура древних людей на севере Казахстана": "💡 La culture de Botaï est la culture de peuples anciens du nord du Kazakhstan",
"💡 Ботайцы считаются одними из первых в мире, кто приручил лошадь": "💡 Les Botaïens sont considérés comme l'un des premiers peuples au monde à avoir domestiqué le cheval",
"💡 Бурабай — красивый курорт с лесом и озёрами в Акмолинской области": "💡 Bourabaï est une belle station avec une forêt et des lacs dans la région d'Aqmola",
"💡 В День Победы вспоминают тех, кто защищал страну в Великой Отечественной войне": "💡 Le jour de la Victoire, on se souvient de ceux qui ont défendu le pays pendant la Grande Guerre patriotique",
"💡 В библиотеке помогают найти нужную книгу": "💡 À la bibliothèque, on aide à trouver le livre dont on a besoin",
"💡 В горах быстро меняется погода и нужны вода и удобная обувь": "💡 En montagne, le temps change vite et il faut de l'eau et des chaussures confortables",
"💡 В горах добывают руду, зимой копится снег, весной он питает реки": "💡 En montagne, on extrait du minerai, en hiver la neige s'accumule, au printemps elle alimente les rivières",
"💡 В грозу прячутся в доме: молния попадает в высокие предметы": "💡 Pendant un orage, on s'abrite dans la maison : la foudre frappe les objets hauts",
"💡 В декабре мы празднуем независимость нашей страны": "💡 En décembre, nous fêtons l'indépendance de notre pays",
"💡 В нашей стране в полдень Солнце стоит на юге": "💡 Dans notre pays, à midi, le Soleil est au sud",
"💡 В семейном архиве хранят старые фотографии, письма и документы": "💡 Dans les archives familiales, on conserve de vieilles photos, des lettres et des documents",
"💡 В словесном портрете рассказывают о внешности и характере человека": "💡 Dans un portrait en mots, on parle de l'apparence et du caractère d'une personne",
"💡 В этот день отмечают дружбу народов нашей страны": "💡 Ce jour-là, on célèbre l'amitié des peuples de notre pays",
"💡 В этот день отмечают дружбу народов страны": "💡 Ce jour-là, on célèbre l'amitié des peuples du pays",
"💡 Верно. Ботайцы охотились на лошадей и приручали их": "💡 Correct. Les Botaïens chassaient les chevaux et les domestiquaient",
