"💡 Верно. В них много витаминов": "💡 Correct. Ils contiennent beaucoup de vitamines",
"💡 Верно. В тумане плохо видно дорогу": "💡 Correct. Dans le brouillard, on voit mal la route",
"💡 Верно. Вежливость и уважение нужны везде: и в школе, и на улице, и в магазине": "💡 Correct. La politesse et le respect sont nécessaires partout : à l'école, dans la rue et au magasin",
"💡 Верно. Вещи можно купить, вырастить, сделать самим или получить в подарок": "💡 Correct. On peut acheter les choses, les cultiver, les fabriquer soi-même ou les recevoir en cadeau",
"💡 Верно. Врач, пожарный, учитель служат обществу своей работой": "💡 Correct. Le médecin, le pompier, l'enseignant servent la société par leur travail",
"💡 Верно. Где-то холодные зимы, где-то мало воды, но везде есть и хорошее": "💡 Correct. Ici, les hivers sont froids, là il y a peu d'eau, mais partout il y a aussi du bon",
"💡 Верно. Герб показывает, что документ выдало государство": "💡 Correct. Les armoiries montrent que le document a été délivré par l'État",
"💡 Верно. Государственные праздники напоминают нам о важном для всей страны": "💡 Correct. Les fêtes nationales nous rappellent ce qui est important pour tout le pays",
