"💡 Верно. Директор руководит школой": "💡 Correct. Le directeur dirige l'école",
"💡 Верно. Дождь поит землю": "💡 Correct. La pluie arrose la terre",
"💡 Верно. Его создали ветер и вода за миллионы лет": "💡 Correct. Il a été créé par le vent et l'eau en des millions d'années",
"💡 Верно. Еда и вода нужны человеку каждый день": "💡 Correct. La nourriture et l'eau sont nécessaires à l'homme chaque jour",
