"💡 Верно. Зимой в горах много снега": "💡 Correct. En hiver, il y a beaucoup de neige dans les montagnes",
"💡 Верно. Извинение помогает сохранить дружбу": "💡 Correct. S'excuser aide à préserver l'amitié",
"💡 Верно. Казахский язык — государственный, а русский используется наравне с ним": "💡 Correct. Le kazakh est la langue d'État, et le russe est utilisé à égalité avec lui",
"💡 Верно. Когда люди разных народов дружат, страна сильнее": "💡 Correct. Quand les gens de différents peuples sont amis, le pays est plus fort",
"💡 Верно. Компас помогает найти север, а потом остальные стороны": "💡 Correct. La boussole aide à trouver le nord, puis les autres points cardinaux",
