"💡 Верно. Маленькие добрые дела делают жизнь вокруг лучше": "💡 Correct. Les petites bonnes actions améliorent la vie autour de nous",
"💡 Верно. Многообразие культур делает страну богаче": "💡 Correct. La diversité des cultures enrichit le pays",
"💡 Верно. На озёрах купаются, катаются на лодках и наблюдают за птицами": "💡 Correct. Sur les lacs, on se baigne, on fait du bateau et on observe les oiseaux",
"💡 Верно. На старых снимках видно, как выглядели наши близкие": "💡 Correct. Sur les vieilles photos, on voit à quoi ressemblaient nos proches",
"💡 Верно. На уроке мы учимся": "💡 Correct. En cours, nous apprenons",
"💡 Верно. Наурыз отмечают весной, когда природа просыпается": "💡 Correct. Nauryz se célèbre au printemps, quand la nature se réveille",
