"💡 Без воды растение не растёт и вянет.": "💡 Sans eau, la plante ne pousse pas et se fane.",
"💡 Без света растение не может нормально расти.": "💡 Sans lumière, la plante ne peut pas bien pousser.",
"💡 Безопасность важна при любом исследовании.": "💡 La sécurité est importante dans toute recherche.",
"💡 Белая шерсть сливается со снегом. Хищнику труднее найти зайца.": "💡 Le pelage blanc se confond avec la neige. Il est plus difficile pour un prédateur de trouver le lièvre.",
"💡 Береги природу и не обижай животных.": "💡 Protège la nature et ne fais pas de mal aux animaux.",
"💡 Береги то, что растёт: сажай, поливай, не ломай.": "💡 Protège ce qui pousse : plante, arrose, ne casse pas.",
"💡 Благодаря Солнцу на Земле тепло и светло, и растут растения.": "💡 Grâce au Soleil, il fait chaud et clair sur Terre, et les plantes poussent.",
"💡 Больные молочные зубы могут испортить и постоянные. Чистить надо всегда.": "💡 Des dents de lait malades peuvent abîmer les dents définitives. Il faut toujours les brosser.",
"💡 Браконьеры убивают животных, а без леса животным негде жить.": "💡 Les braconniers tuent les animaux, et sans forêt les animaux n'ont nulle part où vivre.",
"💡 Бумагу делают из древесины. Это растительный ресурс.": "💡 Le papier est fait de bois. C'est une ressource végétale.",
"💡 В Красную книгу записывают тех, кому грозит исчезновение.": "💡 On inscrit au Livre rouge ceux qui risquent de disparaître.",
"💡 В Красную книгу записывают тех, кто может исчезнуть. Их охраняют.": "💡 On inscrit au Livre rouge ceux qui peuvent disparaître. On les protège.",
"💡 В воздухе есть кислород. Он нужен для дыхания.": "💡 Dans l'air, il y a de l'oxygène. Il est nécessaire à la respiration.",
"💡 В году 12 месяцев.": "💡 Une année compte 12 mois.",
