"💡 Водяной пар — вода в виде газа.": "💡 La vapeur d'eau, c'est de l'eau sous forme de gaz.",
"💡 Воздух есть везде: даже в «пустом» стакане.": "💡 L'air est partout : même dans un verre « vide ».",
