"💡 Воздушная оболочка защищает всё живое на Земле.": "💡 L'enveloppe d'air protège tous les êtres vivants sur Terre.",
"💡 Воробьи и вороны зимуют рядом с людьми.": "💡 Les moineaux et les corbeaux passent l'hiver près des gens.",
"💡 Восьмая от Солнца планета — Нептун.": "💡 La huitième planète à partir du Soleil est Neptune.",
"💡 Врач заметит проблему вовремя.": "💡 Le médecin remarquera le problème à temps.",
"💡 Газ принимает форму того, что его заполняет.": "💡 Un gaz prend la forme de ce qui le contient.",
"💡 Гепард — самое быстрое животное на суше.": "💡 Le guépard est l'animal le plus rapide sur terre.",
"💡 Гипотеза — это предположение, которое мы проверяем опытом.": "💡 Une hypothèse est une supposition que nous vérifions par l'expérience.",
"💡 Глина — минеральный ресурс.": "💡 L'argile est une ressource minérale.",
"💡 Гром — очень громкий звук.": "💡 Le tonnerre est un son très fort.",
"💡 Громкие звуки вредят слуху. Музыку лучше слушать негромко.": "💡 Les sons forts nuisent à l'ouïe. Il vaut mieux écouter la musique doucement.",
"💡 Гусеница превращается в куколку, а из куколки выходит бабочка.": "💡 La chenille se transforme en chrysalide, et de la chrysalide sort un papillon.",
