"💡 Движение — это изменение положения тела.": "💡 Le mouvement, c'est le changement de position du corps.",
"💡 Дерево магнит не притягивает.": "💡 Le bois n'attire pas l'aimant.",
"💡 Дерево непрозрачное.": "💡 Le bois est opaque.",
"💡 Деревья очищают воздух и защищают животных.": "💡 Les arbres purifient l'air et protègent les animaux.",
"💡 Длину измеряют линейкой.": "💡 La longueur se mesure avec une règle.",
"💡 Для прорастания нужны тепло, вода и воздух.": "💡 Pour germer, il faut de la chaleur, de l'eau et de l'air.",
"💡 До Луны ракете нужно лететь несколько суток.": "💡 Pour aller à la Lune, une fusée doit voler plusieurs jours.",
"💡 Дождь обозначают тучкой с каплями.": "💡 La pluie se représente par un nuage avec des gouttes.",
"💡 Дышат все живые существа.": "💡 Tous les êtres vivants respirent.",
"💡 Заповедник Аксу-Жабаглы создан в 1926 году. Он расположен в горах.": "💡 La réserve d'Aksou-Jabagly a été créée en 1926. Elle est située dans les montagnes.",
"💡 Звук возникает, когда тело дрожит (колеблется).": "💡 Le son apparaît quand un corps vibre (oscille).",
"💡 Земля летит вокруг Солнца около 365 суток. Это год.": "💡 La Terre tourne autour du Soleil en environ 365 jours. C'est une année.",
"💡 Земля поворачивается, и Солнце освещает то одну её сторону, то другую.": "💡 La Terre tourne, et le Soleil éclaire tantôt un de ses côtés, tantôt l'autre.",
"💡 Земля притягивает воду. Поэтому реки текут вниз.": "💡 La Terre attire l'eau. C'est pourquoi les rivières coulent vers le bas.",
