"💡 Зимой мало воды и света. Без листьев дерево тратит меньше сил.": "💡 En hiver, il y a peu d'eau et de lumière. Sans feuilles, l'arbre dépense moins d'énergie.",
"💡 Знак заменяет несколько слов. Запись получается короткой и понятной.": "💡 Un symbole remplace plusieurs mots. La note devient courte et claire.",
"💡 Зоолог изучает животных. Он знает о них много проверенных фактов.": "💡 Le zoologiste étudie les animaux. Il connaît beaucoup de faits vérifiés sur eux.",
"💡 Зубы нужно беречь, пока они здоровы.": "💡 Il faut prendre soin des dents tant qu'elles sont saines.",
"💡 Из икринок появляются мальки.": "💡 Des œufs de poisson naissent les alevins.",
"💡 Из семени развивается новое растение.": "💡 De la graine se développe une nouvelle plante.",
"💡 Иртыш течёт по востоку и северу Казахстана.": "💡 L'Irtych coule à l'est et au nord du Kazakhstan.",
"💡 Испарение — переход из жидкого состояния в газообразное.": "💡 L'évaporation est le passage de l'état liquide à l'état gazeux.",
"💡 Исследователь записывает только то, что увидел на самом деле.": "💡 Le chercheur note seulement ce qu'il a réellement vu.",
"💡 Исследователь знает, что хочет узнать (цель), и продумывает, как это сделать (план).": "💡 Le chercheur sait ce qu'il veut découvrir (l'objectif) et réfléchit à la façon de le faire (le plan).",
"💡 Исследователь терпеливый. Он ищет причину и пробует ещё раз.": "💡 Le chercheur est patient. Il cherche la cause et essaie encore.",
"💡 Исследователь умеет ждать: многие результаты появляются не сразу.": "💡 Le chercheur sait attendre : beaucoup de résultats n'apparaissent pas tout de suite.",
"💡 Источник информации — это книга, человек, прибор или предмет, откуда мы получаем знания.": "💡 Une source d'information est un livre, une personne, un appareil ou un objet d'où nous tirons des connaissances.",
"💡 К осени плоды и семена созревают.": "💡 En automne, les fruits et les graines mûrissent.",
