"💡 Когда мы сами смотрим и записываем, наблюдение становится источником знаний.": "💡 Quand nous regardons et notons nous-mêmes, l'observation devient une source de connaissances.",
"💡 Колодцы копают, чтобы достать воду из-под земли.": "💡 On creuse des puits pour puiser l'eau sous la terre.",
