"💡 Кувшинка растёт в воде, а кактус — в сухих местах.": "💡 Le nénuphar pousse dans l'eau, et le cactus dans les endroits secs.",
"💡 Ледники тают и дают воду рекам.": "💡 Les glaciers fondent et donnent de l'eau aux rivières.",
"💡 Лес, вода, нефть, уголь — природные ресурсы.": "💡 La forêt, l'eau, le pétrole, le charbon sont des ressources naturelles.",
"💡 Летом тепло и много света.": "💡 En été, il fait chaud et il y a beaucoup de lumière.",
