"💡 Луна вращается вокруг Земли.": "💡 La Lune tourne autour de la Terre.",
"💡 Луна не светится. Мы видим её, потому что она отражает солнечный свет.": "💡 La Lune ne brille pas d'elle-même. Nous la voyons parce qu'elle reflète la lumière du Soleil.",
"💡 Луна — спутник Земли. Она обращается вокруг неё около месяца.": "💡 La Lune est le satellite de la Terre. Elle tourne autour d'elle en environ un mois.",
"💡 Лупа увеличивает предмет, и мелкие детали становятся видны.": "💡 La loupe agrandit l'objet, et les petits détails deviennent visibles.",
