"💡 Лягушка живёт и в воде, и на суше. Кожа у неё голая и влажная.": "💡 La grenouille vit dans l'eau comme sur terre. Sa peau est nue et humide.",
"💡 Лёд тает и превращается в воду.": "💡 La glace fond et se transforme en eau.",
"💡 Лёд — твёрдая вода.": "💡 La glace, c'est de l'eau solide.",
"💡 Магнит притягивает железо и сталь.": "💡 L'aimant attire le fer et l'acier.",
"💡 Магнит притягивает железо сквозь стекло.": "💡 L'aimant attire le fer à travers le verre.",
"💡 Магниты нужны во многих вещах.": "💡 Les aimants sont nécessaires dans beaucoup d'objets.",
"💡 Марс гораздо дальше Луны. Дорога занимает месяцы.": "💡 Mars est beaucoup plus loin que la Lune. Le trajet prend des mois.",
"💡 Марс красноватый из-за красной пыли и камней.": "💡 Mars est rougeâtre à cause de la poussière et des pierres rouges.",
"💡 Маскировка помогает прятаться от врагов.": "💡 Le camouflage aide à se cacher des ennemis.",
"💡 Масса одинаковая: каждый по одному килограмму.": "💡 La masse est la même : un kilogramme chacun.",
"💡 Масса слона несколько тонн.": "💡 La masse d'un éléphant fait plusieurs tonnes.",
"💡 Массу измеряют в граммах, килограммах, тоннах.": "💡 La masse se mesure en grammes, kilogrammes, tonnes.",
"💡 Меркурий ближе всех к Солнцу. Его год всего 88 земных суток.": "💡 Mercure est la planète la plus proche du Soleil. Son année ne dure que 88 jours terrestres.",
