"💡 Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран, Нептун.": "💡 Mercure, Vénus, Terre, Mars, Jupiter, Saturne, Uranus, Neptune.",
"💡 Многие явления происходят медленно, и нужно подождать.": "💡 Beaucoup de phénomènes se produisent lentement, et il faut attendre.",
"💡 Молоко и сыр дают зубам кальций.": "💡 Le lait et le fromage apportent du calcium aux dents.",
"💡 Молоко получают от животных.": "💡 Le lait provient des animaux.",
