"Камыш растёт у воды, на болотах.": "Le roseau pousse au bord de l'eau, dans les marais.",
"Карагач — дерево с густой кроной.": "L'orme est un arbre à la couronne dense.",
"Карась покрыт чешуёй и дышит жабрами.": "Le carassin est couvert d'écailles et respire avec des branchies.",
