"Верно ли?<br><b>В воздухе есть кислород, которым мы дышим.</b>": "Est-ce vrai ?<br><b>Dans l'air, il y a de l'oxygène que nous respirons.</b>",
"Верно ли?<br><b>Воздух бесцветный.</b>": "Est-ce vrai ?<br><b>L'air est incolore.</b>",
"Верно ли?<br><b>Воздух заполняет всё пространство.</b>": "Est-ce vrai ?<br><b>L'air remplit tout l'espace.</b>",
"Верно ли?<br><b>Воздух имеет запах.</b>": "Est-ce vrai ?<br><b>L'air a une odeur.</b>",
"Верно ли?<br><b>Воздух имеет свою форму.</b>": "Est-ce vrai ?<br><b>L'air a sa propre forme.</b>",
"Верно ли?<br><b>Воздух — это жидкость.</b>": "Est-ce vrai ?<br><b>L'air est un liquide.</b>",
"Верно ли?<br><b>Для роста растению нужен свет.</b>": "Est-ce vrai ?<br><b>Pour pousser, la plante a besoin de lumière.</b>",
"Верно ли?<br><b>Зубы чистят утром и вечером.</b>": "Est-ce vrai ?<br><b>On se brosse les dents matin et soir.</b>",
"Верно ли?<br><b>Исследователь замечает мелочи.</b>": "Est-ce vrai ?<br><b>Le chercheur remarque les détails.</b>",
"Верно ли?<br><b>Исследователь записывает то, что хочет увидеть, а не то, что видит.</b>": "Est-ce vrai ?<br><b>Le chercheur note ce qu'il veut voir, et non ce qu'il voit.</b>",
"Верно ли?<br><b>Исследователь сдаётся сразу, если опыт не получился.</b>": "Est-ce vrai ?<br><b>Le chercheur abandonne tout de suite si l'expérience n'a pas réussi.</b>",
"Верно ли?<br><b>Исследователь соблюдает правила безопасности.</b>": "Est-ce vrai ?<br><b>Le chercheur respecte les règles de sécurité.</b>",
"Верно ли?<br><b>Конфеты полезны для зубов.</b>": "Est-ce vrai ?<br><b>Les bonbons sont bons pour les dents.</b>",
"Верно ли?<br><b>Молочные зубы можно не чистить, они всё равно выпадут.</b>": "Est-ce vrai ?<br><b>On peut ne pas brosser les dents de lait, elles vont tomber de toute façon.</b>",
"Верно ли?<br><b>Незнакомые ягоды можно пробовать на вкус.</b>": "Est-ce vrai ?<br><b>On peut goûter les baies inconnues.</b>",
"Верно ли?<br><b>Опыт с растением в темноте покажет, нужен ли ему свет.</b>": "Est-ce vrai ?<br><b>L'expérience avec la plante dans l'obscurité montrera si elle a besoin de lumière.</b>",
"Верно ли?<br><b>Осанку нужно беречь с детства.</b>": "Est-ce vrai ?<br><b>Il faut protéger sa posture dès l'enfance.</b>",
