"Что выполнит исполнитель?: Алгоритм: если звенит звонок — идти в класс, иначе — играть. Звонка нет. Что делает ученик?": "Qu'exécutera l'exécutant ? : Algorithme : si la sonnerie retentit — aller en classe, sinon — jouer. Il n'y a pas de sonnerie. Que fait l'élève ?",
"Что выполнит исполнитель?: Алгоритм: если идёт дождь — взять зонт, иначе — шапку. Дождя нет. Что возьмёт исполнитель?": "Qu'exécutera l'exécutant ? : Algorithme : s'il pleut — prendre un parapluie, sinon — un bonnet. Il ne pleut pas. Que prendra l'exécutant ?",
"Что выполнит исполнитель?: Алгоритм: если идёт дождь — взять зонт, иначе — шапку. Идёт дождь. Что возьмёт исполнитель?": "Qu'exécutera l'exécutant ? : Algorithme : s'il pleut — prendre un parapluie, sinon — un bonnet. Il pleut. Que prendra l'exécutant ?",
"Что выполнит исполнитель?: Алгоритм: если светофор красный — стоять, иначе — идти. Светофор зелёный. Что делает исполнитель?": "Qu'exécutera l'exécutant ? : Algorithme : si le feu est rouge — s'arrêter, sinon — avancer. Le feu est vert. Que fait l'exécutant ?",
"Что выполнит исполнитель?: Алгоритм: если светофор красный — стоять, иначе — идти. Светофор красный. Что делает исполнитель?": "Qu'exécutera l'exécutant ? : Algorithme : si le feu est rouge — s'arrêter, sinon — avancer. Le feu est rouge. Que fait l'exécutant ?",
"Что выполнит исполнитель?: Алгоритм: если число чётное — прибавить 1, иначе — вычесть 1. Число 5. Что получится?": "Qu'exécutera l'exécutant ? : Algorithme : si le nombre est pair — ajouter 1, sinon — retirer 1. Le nombre est 5. Qu'obtient-on ?",
"Что выполнит исполнитель?: Алгоритм: если число чётное — прибавить 1, иначе — вычесть 1. Число 8. Что получится?": "Qu'exécutera l'exécutant ? : Algorithme : si le nombre est pair — ajouter 1, sinon — retirer 1. Le nombre est 8. Qu'obtient-on ?",
